import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        long t = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        long w = t + 1;
        Map<Long, Long> buckets = new HashMap<>();
        boolean found = false;
        for (int i = 0; i < n && !found; i++) {
            long b = Math.floorDiv(a[i], w);
            if (buckets.containsKey(b)) found = true;
            else if (buckets.containsKey(b - 1) && a[i] - buckets.get(b - 1) <= t) found = true;
            else if (buckets.containsKey(b + 1) && buckets.get(b + 1) - a[i] <= t) found = true;
            if (found) break;
            buckets.put(b, a[i]);
            if (i >= k) buckets.remove(Math.floorDiv(a[i - (int) k], w));
        }
        System.out.println(found ? "yes" : "no");
    }
}
